dtsPropsFor.Button:
/** Button label / content. */
children: React.ReactNode;
/** Visual style. Default 'primary'. */
variant?: 'primary' | 'secondary' | 'outline';
/** Size. Default 'md'. */
size?: 'sm' | 'md' | 'lg';
/** If set, renders as a link. Internal paths route via react-router; http(s) opens in a new tab. */
href?: string;
onClick?: () => void;
className?: string;
/** Native button type when not a link. Default 'button'. */
type?: 'button' | 'submit' | 'reset';
disabled?: boolean;

dtsPropsFor.CTABanner:
title: string;
description: string;
primaryButtonText: string;
primaryButtonHref: string;
secondaryButtonText?: string;
secondaryButtonHref?: string;
/** 'default' = dark green banner (default); 'muted' = white banner. */
variant?: 'default' | 'muted';

dtsPropsFor.ImpactCard:
/** Large stat shown when no icon is given, e.g. "500+". */
number: string;
label: string;
description: string;
/** A lucide-react icon component; replaces the number when provided. */
icon?: React.ComponentType<{ size?: number | string; className?: string }>;

dtsPropsFor.ProgramCard:
/** A lucide-react icon component. */
icon: React.ComponentType<{ size?: number | string; className?: string }>;
title: string;
description: string;
/** Optional bullet list rendered under an "Expected Outcomes" heading. */
outcomes?: string[];

dtsPropsFor.SectionHeader:
title: string;
/** Small eyebrow label above the title. */
subtitle?: string;
description?: string;
/** Text alignment. Default 'center'. */
align?: 'left' | 'center';
